import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Загрузка и установка","description":"","frontmatter":{},"headers":[],"relativePath":"ru/document/install.md","filePath":"ru/document/install.md","lastUpdated":1783774350000}`),a={name:`ru/document/install.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="загрузка-и-установка" tabindex="-1">Загрузка и установка <a class="header-anchor" href="#загрузка-и-установка" aria-label="Permalink to “Загрузка и установка”">​</a></h1><h2 id="поддержка-платформ" tabindex="-1">Поддержка платформ <a class="header-anchor" href="#поддержка-платформ" aria-label="Permalink to “Поддержка платформ”">​</a></h2><p>Официальные Release поддерживают следующие платформы</p><table tabindex="0"><thead><tr><th style="text-align:left;">Платформа</th><th style="text-align:left;">Архитектуры</th></tr></thead><tbody><tr><td style="text-align:left;">Windows <sup><a href="#platform-note-1">[1]</a></sup></td><td style="text-align:left;">x86 / amd64 / arm32 / arm64</td></tr><tr><td style="text-align:left;">macOS</td><td style="text-align:left;">amd64 / arm64</td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;">x86 / amd64 / arm / arm64 / mips64 / mips / ppc64 / s390x / riscv64</td></tr><tr><td style="text-align:left;">FreeBSD</td><td style="text-align:left;">x86 / amd64</td></tr><tr><td style="text-align:left;">OpenBSD</td><td style="text-align:left;">x86 / amd64</td></tr></tbody></table><p><small id="platform-note-1">[1] Поддержка Windows 7 в golang официально прекращена. Xray использует patched go и публикует отдельные сборки для этой системы; пользователям Windows 7 следует использовать релизы с суффиксом <code>-win7</code>.</small></p><p>Xray активно отслеживает версии golang. Для информации о минимальной поддерживаемой версии ОС, кроме win7, обращайтесь к актуальным release notes go, соответствующим моменту выпуска.</p><p>Сборки для amd64 v2/v3 и т. п. не предоставляются, как в некоторых похожих проектах, поскольку тестирование не показало значимого прироста производительности, а во многих ключевых функциях уже используется определение возможностей CPU во время выполнения для автоматического задействования расширенных наборов инструкций.</p><h2 id="загрузка-xray" tabindex="-1">Загрузка Xray <a class="header-anchor" href="#загрузка-xray" aria-label="Permalink to “Загрузка Xray”">​</a></h2><p>Предварительно собранные ZIP-архивы с бинарными файлами доступны в <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a>.</p><p>Скачайте архив для своей платформы и распакуйте его, после чего Xray можно использовать.</p><h2 id="проверка-установочных-пакетов" tabindex="-1">Проверка установочных пакетов <a class="header-anchor" href="#проверка-установочных-пакетов" aria-label="Permalink to “Проверка установочных пакетов”">​</a></h2><p>Xray предоставляет два способа проверки:</p><ul><li>SHA1 / SHA256 хэши ZIP-архивов</li><li>Воспроизводимая сборка: см. <a href="./../development/intro/compile.html">Сборка Xray</a></li></ul><h2 id="установка-в-windows" tabindex="-1">Установка в Windows <a class="header-anchor" href="#установка-в-windows" aria-label="Permalink to “Установка в Windows”">​</a></h2><ul><li>Скачайте ZIP-архив для Windows из <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a>. После распаковки вы получите исполняемый файл <code>xray.exe</code>, который затем можно <a href="./command.html">запустить с аргументами командной строки</a></li></ul><h2 id="установка-в-macos" tabindex="-1">Установка в macOS <a class="header-anchor" href="#установка-в-macos" aria-label="Permalink to “Установка в macOS”">​</a></h2><ul><li>Скачайте ZIP-архив для macOS из <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a>. После распаковки вы получите исполняемый файл <code>xray</code>, который затем можно <a href="./command.html">запустить с аргументами командной строки</a></li><li>Установите через менеджер пакетов <a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a>: <code>brew install xray</code></li><li><a href="https://github.com/N4FA/homebrew-xray" target="_blank" rel="noreferrer">homebrew-xray</a>, спасибо <a href="https://github.com/N4FA" target="_blank" rel="noreferrer">@N4FA</a></li></ul><h2 id="установка-в-linux" tabindex="-1">Установка в Linux <a class="header-anchor" href="#установка-в-linux" aria-label="Permalink to “Установка в Linux”">​</a></h2><h3 id="скрипты-и-проекты-для-установки" tabindex="-1">Скрипты и проекты для установки <a class="header-anchor" href="#скрипты-и-проекты-для-установки" aria-label="Permalink to “Скрипты и проекты для установки”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Тип</th><th style="text-align:left;">Проект</th><th style="text-align:left;">Описание</th></tr></thead><tbody><tr><td style="text-align:left;">Linux Script</td><td style="text-align:left;"><a href="https://github.com/XTLS/Xray-install" target="_blank" rel="noreferrer">XTLS/Xray-install</a> (<strong>Официальный</strong>)</td><td style="text-align:left;">Официально поддерживаемый скрипт установки для Linux</td></tr><tr><td style="text-align:left;">Linux Script</td><td style="text-align:left;"><a href="https://github.com/team-cloudchaser/tempest" target="_blank" rel="noreferrer">tempest</a></td><td style="text-align:left;">Поддерживает <a href="https://systemd.io" target="_blank" rel="noreferrer"><code>Systemd</code></a> и <a href="https://github.com/OpenRC/openrc" target="_blank" rel="noreferrer"><code>OpenRC</code></a></td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/zxcvos/Xray-script" target="_blank" rel="noreferrer">Xray-REALITY</a></td><td style="text-align:left;">Решение для установки в один клик</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/aleskxyz/reality-ezpz" target="_blank" rel="noreferrer">reality-ezpz</a></td><td style="text-align:left;">Решение для установки в один клик</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/hello-yunshu/Xray_bash_onekey" target="_blank" rel="noreferrer">Xray_bash_onekey</a></td><td style="text-align:left;">Решение для установки в один клик</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/mack-a/v2ray-agent" target="_blank" rel="noreferrer">v2ray-agent</a></td><td style="text-align:left;">Решение для установки в один клик</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/proxysu/ProxySU" target="_blank" rel="noreferrer">ProxySU</a></td><td style="text-align:left;">Решение для установки в один клик</td></tr><tr><td style="text-align:left;">Magisk</td><td style="text-align:left;"><a href="https://github.com/Asterisk4Magisk/Xray4Magisk" target="_blank" rel="noreferrer">Xray4Magisk</a></td><td style="text-align:left;">Для окружений с Magisk</td></tr><tr><td style="text-align:left;">Magisk</td><td style="text-align:left;"><a href="https://github.com/E7KMbb/Xray_For_Magisk" target="_blank" rel="noreferrer">Xray_For_Magisk</a></td><td style="text-align:left;">Для окружений с Magisk</td></tr></tbody></table><h3 id="менеджеры-пакетов-и-репозитории-дистрибутивов" tabindex="-1">Менеджеры пакетов и репозитории дистрибутивов <a class="header-anchor" href="#менеджеры-пакетов-и-репозитории-дистрибутивов" aria-label="Permalink to “Менеджеры пакетов и репозитории дистрибутивов”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Способ</th><th style="text-align:left;">Проект</th><th style="text-align:left;">Описание</th></tr></thead><tbody><tr><td style="text-align:left;">Arch User Repository</td><td style="text-align:left;"><a href="https://wiki.archlinux.org/index.php/AUR_helpers" target="_blank" rel="noreferrer">AUR helpers</a></td><td style="text-align:left;">Например, с <a href="https://github.com/Jguer/yay" target="_blank" rel="noreferrer">yay</a> установка выполняется командой <code>yay -S xray</code></td></tr><tr><td style="text-align:left;">Arch Linux CN</td><td style="text-align:left;"><a href="https://www.archlinuxcn.org/archlinux-cn-repo-and-mirror/" target="_blank" rel="noreferrer">репозиторий Arch Linux CN</a></td><td style="text-align:left;">После добавления репозитория установите через <code>pacman -S xray</code> от имени root</td></tr><tr><td style="text-align:left;">Linuxbrew</td><td style="text-align:left;"><a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a></td><td style="text-align:left;">Использование такое же, как у Homebrew: <code>brew install xray</code></td></tr><tr><td style="text-align:left;">Gentoo Portage</td><td style="text-align:left;"><a href="https://github.com/microcai/gentoo-zh" target="_blank" rel="noreferrer">Gentoo-zh</a></td><td style="text-align:left;">Подходит для систем с Systemd; установка после добавления Overlay через layman или eselect-repository</td></tr></tbody></table><h2 id="установка-через-docker" tabindex="-1">Установка через Docker <a class="header-anchor" href="#установка-через-docker" aria-label="Permalink to “Установка через Docker”">​</a></h2><p>Сейчас доступны Docker-образы двух разных типов:</p><ul><li><p><a href="https://ghcr.io/xtls/xray-core" target="_blank" rel="noreferrer">ghcr.io/xtls/xray-core</a> (<strong>Официальный</strong>)<br> Не имеет root-прав, не содержит shell-окружения и поддерживает больше архитектур. Компилируется и собирается из официального репозитория с поддержкой отслеживаемости. Удобство принесено в жертву ради более строгой безопасности.</p><details class="details custom-block"><summary>Структура файлов</summary><ul><li><code>/usr/local/bin/xray</code>: основная программа Xray (владелец: <code>root:root</code>, права на файл: <code>755</code>)</li><li><code>/usr/local/etc/xray/</code>: каталог конфигурационных файлов (точка монтирования) (владелец: <code>root:root</code>, права на каталог: <code>755</code>, права на файлы: <code>644</code>) <ul><li>00_log.json</li><li>01_api.json</li><li>02_dns.json</li><li>03_routing.json</li><li>04_policy.json</li><li>05_inbounds.json</li><li>06_outbounds.json</li><li>07_stats.json</li><li>08_fakedns.json</li><li>09_metrics.json</li><li>10_observatory.json</li><li>11_geodata.json</li><li>12_env.json</li><li>99_version.json</li></ul></li><li><code>/usr/local/share/xray/</code>: каталог файлов ресурсов с геоданными Loyalsoldier (владелец: <code>65532:65532</code>, права на каталог: <code>755</code>, права на файлы: <code>644</code>) <ul><li>geoip.dat</li><li>geosite.dat</li></ul></li><li><code>/var/log/xray/</code>: каталог логов (точка монтирования) (владелец каталога: <code>root:root</code>, права: <code>755</code>; владелец файлов: <code>65532:65532</code>, права: <code>600</code>) <ul><li>access.log</li><li>error.log</li></ul></li></ul></details></li><li><p><a href="https://hub.docker.com/r/teddysun/xray" target="_blank" rel="noreferrer">teddysun/xray</a><br> Имеет root-права, shell-окружение и совместим со всеми архитектурами, поддерживаемыми Alpine. Компилируется и собирается на частном сервере <code>dl.lamp.sh</code>. Более удобен в использовании.</p><details class="details custom-block"><summary>Структура файлов</summary><ul><li><code>/usr/bin/xray</code>: основная программа Xray</li><li><code>/etc/xray/config.json</code>: единый конфигурационный файл (его родительский каталог является точкой монтирования)</li><li><code>/usr/share/xray/</code>: каталог файлов ресурсов с геоданными v2fly <ul><li>geoip.dat</li><li>geosite.dat</li></ul></li></ul></details></li></ul><h2 id="сторонние-графические-клиенты" tabindex="-1">Сторонние графические клиенты <a class="header-anchor" href="#сторонние-графические-клиенты" aria-label="Permalink to “Сторонние графические клиенты”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Платформа</th><th style="text-align:left;">Проект</th></tr></thead><tbody><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/Openwrt-Passwall/openwrt-passwall" target="_blank" rel="noreferrer">PassWall</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/Openwrt-Passwall/openwrt-passwall2" target="_blank" rel="noreferrer">PassWall 2</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/fw876/helloworld" target="_blank" rel="noreferrer">ShadowSocksR Plus+</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/yichya/luci-app-xray" target="_blank" rel="noreferrer">luci-app-xray</a> (<a href="https://github.com/yichya/openwrt-xray" target="_blank" rel="noreferrer">openwrt-xray</a>)</td></tr><tr><td style="text-align:left;">Asuswrt-Merlin</td><td style="text-align:left;"><a href="https://github.com/DanielLavrushin/asuswrt-merlin-xrayui" target="_blank" rel="noreferrer">XRAYUI</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/InvisibleManVPN/InvisibleMan-XRayClient" target="_blank" rel="noreferrer">Invisible Man - Xray</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayNG" target="_blank" rel="noreferrer">v2rayNG</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/XTLS/X-flutter" target="_blank" rel="noreferrer">X-flutter</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/SaeedDev94/Xray" target="_blank" rel="noreferrer">SaeedDev94/Xray</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/lhear/SimpleXray" target="_blank" rel="noreferrer">SimpleXray</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/happ-proxy-utility/id6504287215" target="_blank" rel="noreferrer">Happ</a> (<a href="https://apps.apple.com/us/app/happ-proxy-utility-for-tv/id6748297274" target="_blank" rel="noreferrer">tvOS</a>)</td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/foxray/id6448898396" target="_blank" rel="noreferrer">FoXray</a></td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/streisand/id6450534064" target="_blank" rel="noreferrer">Streisand</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://apps.apple.com/app/happ-proxy-utility/id6504287215" target="_blank" rel="noreferrer">Happ</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/yanue/V2rayU" target="_blank" rel="noreferrer">V2rayU</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/tzmax/V2RayXS" target="_blank" rel="noreferrer">V2RayXS</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/OneXray/OneXray" target="_blank" rel="noreferrer">OneXray</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/goxray/desktop" target="_blank" rel="noreferrer">GoXRay</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/ketetefid/GorzRay" target="_blank" rel="noreferrer">GorzRay</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/goxray/desktop" target="_blank" rel="noreferrer">GoXRay</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr></tbody></table><h2 id="генератор-uuid" tabindex="-1">Генератор UUID <a class="header-anchor" href="#генератор-uuid" aria-label="Permalink to “Генератор UUID”">​</a></h2><p>Сторонний генератор UUID: <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">uuidgenerator.net</a></p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};